hnical details or to contribute feedback"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"⏰ Historical record","marks":[{"type":"bold"}]},{"type":"text","text":" - Browse through past updates to see how the platform has evolved"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This self-updating changelog ensures you''ll never miss an improvement to Rawkode Academy. It''s our commitment to transparency and keeping our community informed about every enhancement we make to your learning experience."}]}]}', 1764608082000);
INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2025-05-25-command-palette', '🎉 New Feature: Command Palette', 1748171135023, 'feature', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We''ve added a "},{"type":"text","text":"powerful command palette","marks":[{"type":"bold"}]},{"type":"text","text":" to enhance your navigation experience on Rawkode Academy!"}]},{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Press "},{"type":"text","text":"Ctrl+K","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"Cmd+K","marks":[{"type":"code"}]},{"type":"text","text":" on Mac) to instantly access the new command palette"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Search and jump to any course, lesson, or resource","marks":[{"type":"bold"}]},{"type":"text","text":" without clicking through menus"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Execute common actions","marks":[{"type":"bold"}]},{"type":"text","text":" like switching themes, accessing your profile, or finding documentation with just a few keystrokes"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"⚡ Lightning-fast navigation","marks":[{"type":"bold"}]},{"type":"text","text":" - Find what you need in seconds, not minutes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 Stay focused","marks":[{"type":"bold"}]},{"type":"text","text":" - Keep your hands on the keyboard and maintain your learning flow"}]}]},