eystrokes"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"⚡ Lightning-fast navigation","marks":[{"type":"bold"}]},{"type":"text","text":" - Find what you need in seconds, not minutes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 Stay focused","marks":[{"type":"bold"}]},{"type":"text","text":" - Keep your hands on the keyboard and maintain your learning flow"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"♿ Improved accessibility","marks":[{"type":"bold"}]},{"type":"text","text":" - Better support for keyboard-only navigation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🔍 Smart search","marks":[{"type":"bold"}]},{"type":"text","text":" - The palette learns from your usage patterns to surface your most-used commands first"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you''re a keyboard warrior or just looking for a faster way to navigate the platform, the command palette puts everything at your fingertips. Try it out by pressing "},{"type":"text","text":"Ctrl+K","marks":[{"type":"code"}]},{"type":"text","text":" anywhere on the site!"}]}]}', 1764608082000);
