INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2025-06-04-rss-feeds', '🎉 New Feature: RSS & Atom Feeds', 1749047280000, 'feature', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Added RSS and Atom feeds for articles, videos, and combined content"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New /feeds page","marks":[{"type":"bold"}]},{"type":"text","text":" - Easily discover and subscribe to any of our content feeds"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multiple feed formats","marks":[{"type":"bold"}]},{"type":"text","text":" - Choose between RSS (.xml) and Atom (.atom) formats"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Organized content","marks":[{"type":"bold"}]},{"type":"text","text":" - Separate feeds for articles, videos, or everything combined"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"📰 Stay updated","marks":[{"type":"bold"}]},{"type":"text","text":" - Never miss new articles or videos with your favorite RSS reader"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🔗 Easy syndication","marks":[{"type":"bold"}]},{"type":"text","text":" - Content can now be easily syndicated and shared across platforms"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"⚡ Faster access","marks":[{"type":"bold"}]},{"type":"text","text":" - Get notifications the moment new content is published"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"📱 Cross-platform","marks":[{"type":"bold"}]},{"type":"text","text":" - Use any RSS reader on any device to follow Rawkode Academy content"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Available feeds include articles-only, videos-only, and a combined feed with all content. Each feed includes proper metadata, descriptions, and direct links to the full content."}]}]}', NULL, 'rawkode', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Added RSS and Atom feeds for articles, videos, and combined content"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New /feeds page","marks":[{"type":"bold"}]},{"type":"text","text":" - Easily discover and subscribe to any of our content feeds"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multiple feed formats","marks":[{"type":"bold"}]},{"type":"text","text":" - Choose between RSS (.xml) and Atom (.atom) formats"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Organized content","marks":[{"type":"bold"}]},{"type":"text","text":" - Separate feeds for articles, videos, or everything combined"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"📰 Stay updated","marks":[{"type":"bold"}]},{"type":"text","text":" - Never miss new articles or videos with your favorite RSS reader"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🔗 Easy syndication","marks":[{"type":"bold"}]},{"type":"text","text":" - Content can now be easily syndicated and shared across platforms"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"⚡ Faster access","marks":[{"type":"bold"}]},{"type":"text","text":" - Get notifications the moment new content is published"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"📱 Cross-platform","marks":[{"type":"bold"}]},{"type":"text","text":" - Use any RSS reader on any device to follow Rawkode Academy content"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Available feeds include articles-only, videos-only, and a combined feed with all content. Each feed includes proper metadata, descriptions, and direct links to the full content."}]}]}', 1764608082000);
INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2025-06-04-video-page-redesign', '🎉 New Feature: Video Page Redesign', 1749076320000, 'feature', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We''ve completely redesigned the video watching experience with a "},{"type":"text","text":"modern, single-column layout","marks":[{"type":"bold"}]},{"type":"text","text":" optimized for learning!"}]},{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Professional single-column layout","marks":[{"type":"bold"}]},{"type":"text","text":" that puts focus on the content"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Social engagement features","marks":[{"type":"bold"}]},{"type":"text","text":" - React, share, and save videos (coming soon banner for now)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tabbed interface","marks":[{"type":"bold"}]},{"type":"text","text":" for Description, Transcript, and Resources with smooth animations"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compact technology pills","marks":[{"type":"bold"}]},{"type":"text","text":" showing the technologies featured in each video"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Improved responsive design","marks":[{"type":"bold"}]},{"type":"text","text":" that works beautifully on all screen sizes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enhanced typography and spacing","marks":[{"type":"bold"}]},{"type":"text","text":" for better readability"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Mat