INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2025-10-01-learning-paths', '🧭 New Feature: Learning Paths Hub', 1759309200000, 'feature', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Build mastery faster with curated learning paths that bundle Rawkode Academy videos into guided journeys. "},{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dedicated hub","marks":[{"type":"bold"}]},{"type":"text","text":" - Explore our new /learning-paths page with a guided learning hero section and polished gradient styling * "},{"type":"text","text":"Smart at-a-glance cards","marks":[{"type":"bold"}]},{"type":"text","text":" - Quickly scan difficulty, estimated runtime, featured technologies, and contributing instructors for each path * "},{"type":"text","text":"Structured path pages","marks":[{"type":"bold"}]},{"type":"text","text":" - Dive into detailed objectives, prerequisite checklists, and sequenced videos with context on why every step matters * "},{"type":"text","text":"Author visibility","marks":[{"type":"bold"}]},{"type":"text","text":" - See who designed each path and when it was published so you can follow their work "},{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 Focused progression","marks":[{"type":"bold"}]},{"type":"text","text":" - Pick the path that matches your skill level and time budget without hunting through dozens of videos * "},{"type":"text","text":"🧵 Connected context","marks":[{"type":"bold"}]},{"type":"text","text":" - Understand how each video builds on the last with clear rationales and takeaways * "},{"type":"text","text":"🚀 Faster onboarding","marks":[{"type":"bold"}]},{"type":"text"