INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2025-12-02-technology-matrix', 'Technology Matrix', 1764666000000, 'feature', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An opinionated guide to cloud native and platform engineering technologies, visualized as a pipeline from discovery to advocacy. "},{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pipeline visualization","marks":[{"type":"bold"}]},{"type":"text","text":" - Technologies organized by adoption stage: Skip, Watch, Explore, Learn, Adopt, and Advocate * "},{"type":"text","text":"Category lanes","marks":[{"type":"bold"}]},{"type":"text","text":" - Browse by CNCF categories like Provisioning, Orchestration, Runtime, Observability, and more * "},{"type":"text","text":"Advanced mode","marks":[{"type":"bold"}]},{"type":"text","text":" - Interactive filtering, grouping, and exploration across all dimensions * "},{"type":"text","text":"Technology cards","marks":[{"type":"bold"}]},{"type":"text","text":" - Click any technology to see why I use it, spicy takes, and trajectory indicators * "},{"type":"text","text":"Graveyard section","marks":[{"type":"bold"}]},{"type":"text","text":" - A resting place for technologies that burned me, were abandoned, or have been superseded "},{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opinionated guidance","marks":[{"type":"bold"}]},{"type":"text","text":" - See where technologies sit in my personal evaluation and adoption journey * "},{"type":"text","text":"Trajectory tracking","marks":[{"type":"bold"}]},{"type":"text","text":" - Know which technologies are rising, stable, or falling in my estimation * "},{"type":"text","text":"Newsletter integration","marks":[{"type":"bold"}]},{"type":"text","text":" - Subscribe to get notified when technologies move through the matrix"}]}]}]}]}', NULL, 'rawkode', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An opinionated guide to cloud native and platform engineering technologies, visualized as a pipeline from discovery to advocacy."}]},{"type":"paragraph","content":[{"type":"text","text":"What''s New:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pipeline visualization","marks":[{"type":"bold"}]},{"type":"text","text":" - Technologies organized by adoption stage: Skip, Watch, Explore, Learn, Adopt, and Advocate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Category lanes","marks":[{"type":"bold"}]},{"type":"text","text":" - Browse by CNCF categories like Provisioning, Orchestration, Runtime, Observability, and more."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Advanced mode","marks":[{"type":"bold"}]},{"type":"text","text":" - Interactive filtering, grouping, and exploration across all dimensions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Technology cards","marks":[{"type":"bold"}]},{"type":"text","text":" - Click any technology to see why I use it, spicy takes, and trajectory indicators."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Graveyard section","marks":[{"type":"bold"}]},{"type":"text","text":" - A resting place for technologies that burned me, were abandoned, or have been superseded."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why This Matters:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opinionated guidance","marks":[{"type":"bold"}]},{"type":"text","text":" - See where technologies sit in my personal evaluation and adoption journey."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trajectory tracking","marks":[{"type":"bold"}]},{"type":"text","text":" - Know which technologies are rising, stable, or falling in my estimation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Newsletter integration","marks":[{"type":"bold"}]},{"type":"text","text":" - Subscribe to get notified when technologies move through the matrix."}]}]}]}]}', 1764689920000);
INSERT INTO `changelog_entries` (`id`, `title`, `date`, `type`, `description`, `pull_request`, `author_id`, `body`, `updated_at`) VALUES ('2026-05-24-site-redesign-and-sharing', 'Site redesign and share previews', 1779624000000, 'improvement', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A broad cleanup across the academy site: simpler collection pages, clearer navigation, stronger Technology Matrix placement, refreshed organization pages, and reliable OpenGraph share images."}]}]}', NULL, 'rawkode', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The site now puts the main learning surfaces first: news, videos, articles, courses, learning paths, shows, technologies, people, and the Technology Matrix."}]},{"type":"paragraph","content":[{"type":"text","text":"This update also cleans up mobile spacing, removes repeated editorial labels, improves watch and article layouts, refreshes the organization pages, and restores large OpenGraph images for social previews."}]}]}', 1779629671000);
